void Awake()  { /* 참조 캐싱 — 자기 자신만 */ }
void Start()  { /* 다른 오브젝트 참조 — 모두 Awake 이후 */ }
void Update()      { /* 매 프레임 — 입력·이동·로직 (game-loop·input) */ }
void FixedUpdate() { /* 물리 프레임 — 물리·리지드바디 (고정 스텝) */ }
void OnDestroy()   { /* 파괴 시 — 정리·구독 해제 */ }

// 순서를 헷갈리면 null 참조
// 「Awake 는 자기 준비, Start 는 남과의 연결」로 기억하면 대부분 해결

// 데이터 자산 (로직 없이 수치만) — Unity ScriptableObject
[CreateAssetMenu]
class WeaponData : ScriptableObject {
  public float damage = 12;
  public float cooldown = 0.4f;
}
// 로직(코드)은 데이터를 참조
class Weapon : MonoBehaviour {
  public WeaponData data;   // 인스펙터에서 자산 연결
  void Attack() { hit(data.damage); }   // 데이터에서 읽음
}
// 수치를 코드에 박으면 조정이 빌드 → 데이터 자산으로 빼 빌드 없이 조정
// Godot: Resource · Unreal: DataAsset (엔진마다 있음)

// ① 매 프레임 Find/GetComponent 하지 않기 (캐싱)
Rigidbody rb;
void Awake() { rb = GetComponent<Rigidbody>(); }   // 한 번 찾아 저장
void Update() { rb.velocity = ...; }               // 매 프레임 재사용(Find X)

// ② 인스턴스화·파괴 반복 대신 풀링 (object pool — game-loop 5장)
// ③ 드로우 콜·물리 충돌 수 확인 (배칭·아틀라스·레이어·단순 충돌체)

// 엔진 프로파일러를 열어 어디서 시간이 가는지 측정 (감이 아니라 관측)
